#!/usr/bin/env python3
"""Regenerate site/js/lab/models/benford-data.js: total population of every country in 2022 (World Bank, indicator SP.POP.TOTL,
licence CC BY 4.0), aggregates (regions, income groups) excluded. Needs network access. The site never fetches this at run time."""
import json, urllib.request, pathlib
get = lambda u: json.load(urllib.request.urlopen(u, timeout=60))
countries = {c['id'] for c in get('https://api.worldbank.org/v2/country?format=json&per_page=400')[1] if c['region']['id'] != 'NA'}
rows = get('https://api.worldbank.org/v2/country/all/indicator/SP.POP.TOTL?date=2022&format=json&per_page=400')
values = sorted(r['value'] for r in rows[1] if r['countryiso3code'] in countries and r['value'])
out = pathlib.Path(__file__).resolve().parent.parent / 'site/js/lab/models/benford-data.js'
out.write_text("// Total population of %d countries in 2022, World Bank indicator SP.POP.TOTL (CC BY 4.0), aggregates excluded.\n// Generated by scripts/fetch-benford-population.py; a real dataset spread over more than five orders of magnitude, used by the Benford laboratory.\nexport const COUNTRY_POPULATIONS_2022 = [%s];\n" % (len(values), ','.join(map(str, values))))
print(len(values), values[:3], values[-3:])
